    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    cores = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if (0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen
                            and grid[ny][nx] == color):
                        seen.add((ny,nx))
                        q.append((ny,nx))
            if len(cells) >= 3:
                ys = [p[0] for p in cells]
                xs = [p[1] for p in cells]
                cores.append((color, min(ys), max(ys), min(xs), max(xs), cells))
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or any(color == core[0] and (r, c) in core[5] for core in cores):
                continue
            candidates = [core for core in cores
                          if core[1] <= r <= core[2] and core[3] <= c <= core[4]]
            if candidates:
                # Select the enclosing component whose bounding box is smallest.
                chosen = min(candidates, key=lambda z: (z[2]-z[1]+1)*(z[4]-z[3]+1))
                out[r][c] = chosen[0]
            else:
                out[r][c] = bg
    return out


if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
